self.FRX=self.FRX||{};(FRX.gx=FRX.gx||{})["de"]={"etre-present":["Être: sein","\"être\" bedeutet 'sein': \"je suis\", \"tu es\", \"il est\", \"nous sommes\", \"vous êtes\", \"ils sont\". Du brauchst es für Identität, Herkunft, Beruf und Beschreibung. Lerne es auswendig: Es ist das häufigste Verb im Französischen. Beispiele: \"je suis\", \"nous sommes\", \"ils sont\""],"avoir-present":["Avoir: haben","\"avoir\" bedeutet 'haben': \"j'ai\", \"tu as\", \"il a\", \"nous avons\", \"vous avez\", \"ils ont\". Später bildet es auch das passé composé. Achte auf die Elision \"j'ai\" vor Vokal. Beispiele: \"j'ai\", \"elle a\", \"nous avons\""],"il-y-a":["Il y a: es gibt","\"il y a\" führt etwas ein, das existiert, im Singular wie im Plural, und verändert sich nie: \"il y a un livre\", \"il y a des livres\". Verneinung: \"il n'y a pas de livre\". Die Frage lautet \"y a-t-il\" oder \"est-ce qu'il y a\". Beispiele: \"il y a un café\", \"il n'y a pas de lait\""],"art-defini":["Bestimmte Artikel","\"le\" (maskulin), \"la\" (feminin), \"l'\" (vor Vokal) und \"les\" (Plural) bedeuten 'der, die, das'. Das Französische nutzt sie auch für allgemeine Aussagen: \"j'aime la musique\" heißt 'ich mag Musik'. Beispiele: \"le café\", \"la pomme\", \"les enfants\""],"art-indefini":["Unbestimmte Artikel","\"un\" (maskulin), \"une\" (feminin) und \"des\" (Plural) bedeuten 'ein, eine' oder 'einige'. Sie führen etwas Neues ein: \"j'ai un frère et des cousins\". Achtung: \"des\" lässt man im Deutschen oft weg. Beispiele: \"un frère\", \"une sœur\", \"des amis\""],"gender-nouns":["Maskulin oder feminin?","Jedes Nomen ist maskulin oder feminin. Endungen helfen: \"-tion\", \"-té\", \"-ette\" sind meist feminin, \"-ment\", \"-age\", \"-eau\" meist maskulin. Lerne ein Nomen immer mit seinem Artikel: \"la ville\", \"le village\". Beispiele: \"le village\", \"la ville\", \"la question\""],"plural-regular":["Plural: -s anhängen","Die meisten Plurale bekommen \"-s\", das man nicht hört: \"un ami\", \"des amis\". Nomen auf \"-s\", \"-x\" oder \"-z\" bleiben gleich: \"un pays\", \"des pays\". Nur Artikel und Liaison verraten den Plural. Beispiele: \"deux sœurs\", \"trois amis\""],"plural-irregular":["Unregelmäßige Plurale","Nomen auf \"-al\" bilden \"-aux\": \"un journal\", \"des journaux\". Nomen auf \"-eau\" und \"-eu\" bekommen \"-x\": \"un bateau\", \"des bateaux\", \"un jeu\", \"des jeux\". Merke dir die wenigen Ausnahmen wie \"un festival, des festivals\". Beispiele: \"des journaux\", \"des bateaux\", \"des cheveux\""],"elision-basic":["Elision vor Vokal","Die kurzen Wörter \"le\", \"la\", \"je\", \"ne\", \"de\", \"que\", \"se\" verlieren vor Vokal oder stummem h ihren Vokal und bekommen einen Apostroph: \"l'école\", \"j'aime\", \"n'aime pas\", \"qu'elle\". \"les\" und \"un\" werden nie elidiert. Beispiele: \"l'école\", \"j'aime\", \"qu'elle\""],"contractions-au-du":["au, aux, du, des","\"à + le\" wird zu \"au\", \"à + les\" zu \"aux\", \"de + le\" zu \"du\", \"de + les\" zu \"des\". Bei \"la\" und \"l'\" ändert sich nichts: \"à la gare\", \"de la gare\". Schreibe nie \"à le\" oder \"de le\". Beispiele: \"au marché\", \"aux voisins\", \"du professeur\""],"partitif":["Teilungsartikel: etwas","Für eine Menge von etwas Unzählbarem nimmst du \"du\" (maskulin), \"de la\" (feminin), \"de l'\" (Vokal) oder \"des\" (Plural): \"je prends du café\". Im Deutschen steht oft kein Wort, im Französischen immer. Beispiele: \"du pain\", \"de la salade\", \"des légumes\""],"de-negation":["Verneinung + de","Nach \"ne… pas\", \"jamais\", \"plus\" wird der unbestimmte Artikel oder Teilungsartikel zu \"de\": \"j'ai un chat\" wird zu \"je n'ai pas de chat\". Ausnahme: Nach \"être\" bleibt der Artikel: \"ce n'est pas un chat\". Beispiele: \"pas de voiture\", \"jamais de viande\""],"adj-agreement":["Angleichung des Adjektivs","Adjektive richten sich nach dem Nomen: \"-e\" im Femininum und \"-s\" im Plural. \"grand\", \"grande\", \"grands\", \"grandes\". Adjektive auf -e bleiben im Femininum gleich: \"un garçon sympa\", \"une fille sympa\". Beispiele: \"elle est grande\", \"ils sont petits\""],"adj-position":["Wo steht das Adjektiv?","Die meisten Adjektive stehen nach dem Nomen: \"une robe bleue\". Einige kurze, häufige stehen davor: Schönheit, Alter, Güte, Größe (\"beau, jeune, bon, grand, petit\"): \"un petit chien\". \"beau\" hat die Formen \"bel\" und \"belle\". Beispiele: \"une belle maison\", \"une maison blanche\""],"possessifs":["Possessiva: mon, ma, mes","Das Possessivum richtet sich nach dem Besitztum, nicht nach dem Besitzer: \"mon père\", \"ma mère\", \"mes parents\". Vor Vokal nehmen feminine Nomen \"mon\": \"mon amie\". Weitere: \"notre/nos\", \"votre/vos\", \"leur/leurs\". Beispiele: \"mon père\", \"ma mère\", \"leurs chats\""],"demonstratifs":["Dieser, jener: ce, cette, ces","\"ce\" (maskulin), \"cet\" (maskulin vor Vokal), \"cette\" (feminin) und \"ces\" (Plural) bedeuten 'dieser' oder 'jener'. Mit \"-ci\" oder \"-là\" setzt du Gegensätze: \"ce livre-ci\", \"ce livre-là\". Beispiele: \"ce livre\", \"cette veste\", \"ces enfants\""],"pres-er":["Présent: Verben auf -er","Streiche \"-er\" und hänge \"-e, -es, -e, -ons, -ez, -ent\" an: \"parler\" ergibt \"je parle\", \"tu parles\", \"il parle\", \"nous parlons\", \"vous parlez\", \"ils parlent\". Etwa 90 Prozent der französischen Verben folgen diesem Muster. Beispiele: \"je parle\", \"nous parlons\", \"ils parlent\""],"pres-ir-re":["Présent: Verben auf -ir und -re","Regelmäßige \"-ir\"-Verben bekommen \"-is, -is, -it, -issons, -issez, -issent\": \"finir\", \"je finis\", \"nous finissons\". \"-re\"-Verben bekommen \"-s, -s, -, -ons, -ez, -ent\": \"vendre\", \"je vends\", \"il vend\". Beispiele: \"je finis\", \"nous finissons\", \"je vends\""],"pres-irreguliers":["Häufige unregelmäßige Verben","Lerne \"aller\" (\"je vais, nous allons\"), \"faire\" (\"je fais, vous faites\"), \"prendre\" (\"je prends, ils prennent\") und \"venir\" (\"je viens, ils viennent\"). Achtung bei \"vous faites\" und \"ils font\": Sie brechen das Muster. Beispiele: \"je vais\", \"nous faisons\", \"ils prennent\", \"vous venez\""],"tu-vous":["Tu oder vous?","Sag \"tu\" zu Freunden, Familie, Kindern und Gleichaltrigen. Sag \"vous\" zu Fremden, älteren Menschen, im Geschäft und bei der Arbeit, und immer, wenn du mehrere Personen ansprichst. Im Zweifel beginne mit \"vous\". Beispiele: \"tu viens\", \"vous venez\""],"on-nous":["On = wir","Im Alltagsfranzösisch ersetzt \"on\" das \"nous\", aber das Verb bleibt in der 3. Person Singular: \"on va au cinéma\". \"On\" bedeutet auch 'man': \"en France, on mange du pain\". Beispiele: \"on va\", \"on mange\""],"neg-ne-pas":["Verneinung: ne … pas","Setze \"ne\" vor das Verb und \"pas\" danach: \"je ne parle pas\". Vor Vokal wird \"ne\" zu \"n'\": \"il n'aime pas\". Gesprochen fällt \"ne\" oft weg, aber schreibe es im korrekten Französisch. Beispiele: \"je ne parle pas\", \"il n'aime pas\""],"q-est-ce-que":["Ja/Nein-Fragen","Am einfachsten: Wortstellung beibehalten und die Stimme heben oder ein Fragezeichen setzen: \"tu viens ?\". Formeller: \"est-ce que\" davor: \"est-ce que tu viens ?\". Vor Vokal wird daraus \"est-ce qu'\": \"est-ce qu'elle vient ?\". Beispiele: \"tu aimes le thé ?\", \"est-ce que vous avez\""],"q-mots-interrogatifs":["Fragewörter","\"où\" (wo), \"quand\" (wann), \"comment\" (wie), \"combien\" (wie viel), \"pourquoi\" (warum), \"qui\" (wer). Sie stehen am Anfang: \"où est la gare ?\". Auf \"pourquoi\" antwortest du mit \"parce que\". Beispiele: \"où\", \"quand\", \"combien\", \"pourquoi\""],"q-quel":["Quel: welcher, was für","\"quel\" richtet sich nach dem Nomen: \"quel\" (m. Sg.), \"quelle\" (f. Sg.), \"quels\" (m. Pl.), \"quelles\" (f. Pl.). Nach \"être\" kann es nach dem Nomen stehen: \"quel est ton nom ?\" Beispiele: \"quelle heure\", \"quels films\""],"futur-proche":["Nahe Zukunft: aller + Infinitiv","Konjugiere \"aller\" im Präsens und hänge einen Infinitiv an: \"je vais travailler\", \"nous allons manger\". Verneinung: \"je ne vais pas partir\". So spricht man meist über Pläne. Beispiele: \"je vais manger\", \"elle va partir\""],"pres-pronominaux":["Reflexive Verben","Diese Verben haben ein Pronomen, das zum Subjekt passt: \"je me\", \"tu te\", \"il se\", \"nous nous\", \"vous vous\", \"ils se\". Beispiele: \"se lever\", \"se coucher\", \"s'habiller\". Verneinung: \"je ne me lève pas\". Beispiele: \"je me lève\", \"elle se couche\""],"imperatif-present":["Imperativ","Nimm die Präsensformen von \"tu\", \"nous\", \"vous\" ohne Pronomen: \"tu parles\" ergibt \"parle !\", \"nous parlons\" ergibt \"parlons !\", \"vous parlez\" ergibt \"parlez !\". \"-er\"-Verben verlieren in der \"tu\"-Form das End-s. Unregelmäßig: \"sois, soyons, soyez\", \"aie, ayons, ayez\". Beispiele: \"parle !\", \"parlons !\", \"parlez !\""],"modaux-pouvoir-vouloir":["vouloir, pouvoir, devoir","Auf diese drei Verben folgt ein Infinitiv: \"je veux manger\", \"tu peux venir\", \"nous devons partir\". Sie sind unregelmäßig: \"je veux, nous voulons\", \"je peux, nous pouvons\", \"je dois, nous devons\". Beispiele: \"je veux partir\", \"tu peux\", \"nous devons\""],"prep-lieu":["Wo ist es?","Häufige Ortswörter: \"dans\" (in), \"sur\" (auf), \"sous\" (unter), \"devant\" (vor), \"derrière\" (hinter), \"entre\" (zwischen), \"à côté de\" (neben), \"près de\" (in der Nähe von). Nach \"de\" denk an die Verschmelzungen: \"à côté du parc\". Beispiele: \"sur la table\", \"sous la table\", \"entre la poste et la banque\""],"prep-a-chez-de":["à, chez, de","\"à\" steht bei Städten und Orten: \"je vais à Lyon\". \"chez\" steht bei Personen oder ihrem Geschäft oder Zuhause: \"chez le dentiste\", \"chez moi\". \"de\" sagt, woher du kommst: \"je viens de Lyon\". Beispiele: \"chez Marie\", \"à Lyon\", \"de la gare\""],"nombres":["Zahlen","Besondere Formen: \"soixante-dix\" (70), \"quatre-vingts\" (80, mit -s), \"quatre-vingt-dix\" (90). \"et\" steht in 21, 31, 41, 51, 61 und 71, aber nicht in 81 und 91. Bindestriche verbinden Zehner und Einer. Beispiele: \"vingt et un\", \"soixante-dix\", \"quatre-vingts\""],"heure-date":["Uhrzeit und Datum","Sag \"il est\" + Stunde: \"il est trois heures et quart\". \"midi\" und \"minuit\" nehmen \"et demi\", andere Stunden \"et demie\". Datum: \"le 5 mai\"; nur der Erste ist eine Ordnungszahl: \"le premier mai\". Die Uhrzeit bildet man mit \"à\": \"à neuf heures\". Beispiele: \"huit heures et demie\", \"le cinq mai\""],"c-est-ce-sont":["C'est, ce sont","Nimm \"c'est\" + Nomen im Singular und \"ce sont\" + Nomen im Plural, um etwas vorzustellen oder zu benennen: \"c'est un livre\", \"ce sont des livres\". Gesprochen ist \"c'est\" auch bei Plural üblich. Frage: \"qu'est-ce que c'est ?\" Beispiele: \"c'est mon frère\", \"ce sont mes amis\""],"gouts-aimer":["Vorlieben und Abneigungen","Nach \"aimer\", \"adorer\", \"détester\" und \"préférer\" steht der bestimmte Artikel, nicht der Teilungsartikel: \"j'aime le café\", \"elle adore les chats\". Dazu passt \"beaucoup\": \"j'aime beaucoup la musique\". Beispiele: \"j'aime le chocolat\", \"je déteste les épinards\""],"adv-intensite":["Wie sehr?","\"très\" steht vor Adjektiven und Adverbien: \"très bien\". \"beaucoup\" steht nach Verben: \"il travaille beaucoup\". Vor einem Nomen heißt es \"beaucoup de\": \"beaucoup de fruits\". \"un peu\" und \"trop\" funktionieren wie \"beaucoup\". Beispiele: \"très grand\", \"il mange beaucoup\", \"un peu\""],"avoir-expressions":["Ausdrücke mit avoir","Das Französische benutzt \"avoir\", nicht \"être\", für das Alter und viele Körpergefühle: \"j'ai vingt ans\", \"j'ai faim\", \"j'ai soif\", \"j'ai chaud\", \"j'ai froid\", \"j'ai peur\", \"j'ai sommeil\". Mit \"très\": \"j'ai très faim\". Beispiele: \"j'ai faim\", \"elle a vingt ans\", \"il a froid\""],"clause-et-mais-parce-que":["Verbindungswörter","\"et\" fügt hinzu, \"ou\" bietet eine Wahl, \"mais\" stellt gegenüber, \"parce que\" gibt einen Grund. Vor Vokal wird \"parce que\" zu \"parce qu'\": \"parce qu'il pleut\". \"donc\" nennt die Folge. Beispiele: \"et\", \"mais\", \"parce que\""],"pc-avoir":["Passé composé mit avoir","Die meisten Verben bilden die Vergangenheit mit \"avoir\" im Präsens + Partizip: \"j'ai mangé\", \"tu as fini\", \"il a vendu\". Partizipien: \"-er\" ergibt \"-é\", \"-ir\" ergibt \"-i\", \"-re\" ergibt \"-u\". Beispiele: \"j'ai mangé\", \"nous avons fini\""],"pc-etre":["Passé composé mit être","Etwa fünfzehn Verben nehmen \"être\": \"aller, venir, arriver, partir, entrer, sortir, monter, descendre, rester, tomber, naître, mourir, retourner, passer\" und alle reflexiven Verben. Eine Gedächtnisstütze ist die Liste \"DR MRS VANDERTRAMP\". Beispiele: \"je suis allé\", \"elle est partie\""],"pc-accord-etre":["Angleichung des Partizips mit être","Mit \"être\" richtet sich das Partizip nach dem Subjekt: \"-e\" im Femininum und \"-s\" im Plural. \"il est parti\", \"elle est partie\", \"ils sont partis\", \"elles sont parties\". Beispiele: \"elle est partie\", \"ils sont venus\", \"elles sont allées\""],"pc-pronominaux":["Reflexive Verben in der Vergangenheit","Reflexive Verben nehmen \"être\", das Pronomen steht davor: \"je me suis levé\", \"elle s'est couchée\", \"ils se sont promenés\". Das Partizip richtet sich meist nach dem Subjekt. Beispiele: \"je me suis levé\", \"elle s'est couchée\""],"pc-negation":["Verneinte Vergangenheit","Setze \"ne … pas\" um das Hilfsverb, nicht um das Partizip: \"je n'ai pas mangé\", \"elle n'est pas venue\". Dasselbe gilt für \"jamais\", \"plus\", \"rien\": \"il n'a rien dit\". Beispiele: \"je n'ai pas mangé\", \"il n'est jamais venu\""],"pc-participes-irreguliers":["Unregelmäßige Partizipien","Wichtige Formen: \"avoir\" ergibt \"eu\", \"être\" ergibt \"été\", \"faire\" ergibt \"fait\", \"prendre\" ergibt \"pris\", \"voir\" ergibt \"vu\", \"dire\" ergibt \"dit\", \"écrire\" ergibt \"écrit\", \"mettre\" ergibt \"mis\", \"pouvoir\" ergibt \"pu\", \"vouloir\" ergibt \"voulu\". Beispiele: \"j'ai eu\", \"j'ai été\", \"il a fait\", \"elle a pris\""],"imparfait-formation":["Imparfait: Formen","Nimm die \"nous\"-Form des Präsens, streiche \"-ons\" und hänge \"-ais, -ais, -ait, -ions, -iez, -aient\" an: \"nous parlons\" ergibt \"je parlais\". Nur \"être\" ist unregelmäßig: \"j'étais, nous étions\". Beispiele: \"je jouais\", \"nous allions\", \"il était\""],"imparfait-usage":["Imparfait: wann man es benutzt","Der \"imparfait\" beschreibt den Hintergrund einer Geschichte: Wetter, Gefühle, Beschreibungen und wiederholte Gewohnheiten. \"Il faisait beau\", \"j'étais fatigué\", \"chaque été, nous allions à la mer\". Beispiele: \"il faisait beau\", \"je jouais\", \"nous habitions\""],"impf-vs-pc":["Imparfait oder passé composé?","\"Imparfait\": was gerade lief, der Rahmen. \"Passé composé\": was geschah, ein einzelnes Ereignis, das die Geschichte vorantreibt. \"Je lisais quand le téléphone a sonné\": Das Lesen lief, das Klingeln unterbrach es. Beispiele: \"je dormais\", \"le téléphone a sonné\""],"futur-simple":["Futur simple","Nimm den Infinitiv (bei \"-re\"-Verben fällt das End-e weg) und hänge \"-ai, -as, -a, -ons, -ez, -ont\" an: \"parler\" ergibt \"je parlerai\", \"prendre\" ergibt \"je prendrai\". Beispiele: \"je parlerai\", \"nous prendrons\", \"ils finiront\""],"futur-irreguliers":["Unregelmäßige Futurstämme","Die Endungen bleiben gleich, aber der Stamm ändert sich: \"aller\" ergibt \"ir-\", \"être\" ergibt \"ser-\", \"avoir\" ergibt \"aur-\", \"faire\" ergibt \"fer-\", \"venir\" ergibt \"viendr-\", \"pouvoir\" ergibt \"pourr-\", \"voir\" ergibt \"verr-\", \"vouloir\" ergibt \"voudr-\". Beispiele: \"j'irai\", \"il fera\", \"ils viendront\""],"conditionnel-politesse":["Höflicher Konditional","Der \"conditionnel\" macht Bitten weicher: \"je voudrais\" (ich möchte), \"pourriez-vous\" (könnten Sie), \"j'aimerais\" (ich würde gern). Bildung: Futurstamm + Endungen des Imparfait \"-ais, -ais, -ait, -ions, -iez, -aient\". Beispiele: \"je voudrais\", \"pourriez-vous\", \"nous aimerions\""],"cod-pronoms":["Pronomen des direkten Objekts","\"le\", \"la\", \"l'\" und \"les\" ersetzen ein Nomen ohne Präposition und stehen vor dem Verb: \"je vois Paul\" wird zu \"je le vois\". Verneinung: \"je ne le vois pas\". Beispiele: \"je le vois\", \"elle la prend\", \"tu les aimes\""],"coi-pronoms":["Pronomen des indirekten Objekts","Für Personen nach \"à\" nimm \"lui\" (ihm oder ihr) und \"leur\" (ihnen): \"je parle à Marie\" wird zu \"je lui parle\", \"je téléphone à mes parents\" wird zu \"je leur téléphone\". \"leur\" bekommt hier nie ein -s. Beispiele: \"je lui parle\", \"elle leur écrit\""],"pronoms-me-te-nous-vous":["me, te, nous, vous","Diese vier Pronomen gelten für direkte und indirekte Objekte: \"il me voit\", \"il me parle\". Vor Vokal werden \"me\" und \"te\" zu \"m'\" und \"t'\": \"je t'aime\", \"il m'écoute\". Beispiele: \"il me voit\", \"elle nous parle\""],"y-pronom":["Das Pronomen y","\"y\" ersetzt \"à\" + Sache oder einen Ort: \"je vais à Rome\" wird zu \"j'y vais\". Es steht vor dem Verb: \"nous y allons\", \"je n'y vais pas\". Auch \"j'y pense\". Beispiele: \"j'y vais\", \"nous y allons\""],"en-pronom":["Das Pronomen en","\"en\" ersetzt \"du, de la, des\" + Nomen oder \"de\" + Nomen. Die Zahl bleibt: \"j'ai deux frères\" wird zu \"j'en ai deux\". Verneinung: \"je n'en veux pas\". Beispiele: \"j'en veux\", \"nous en avons deux\""],"pronoms-toniques":["Betonte Pronomen","Benutze \"moi, toi, lui, elle, nous, vous, eux, elles\" nach Präpositionen (\"avec moi\", \"chez eux\"), zur Betonung (\"moi, je\") und allein (\"Qui est là ? Moi !\"). Auch nach \"c'est\": \"c'est lui\". Beispiele: \"avec moi\", \"chez lui\", \"eux\""],"comparatifs":["Vergleichen: plus … que","Nimm \"plus … que\" (mehr), \"moins … que\" (weniger) und \"aussi … que\" (so … wie) um ein Adjektiv oder Adverb: \"elle est plus rapide que lui\". Bei Nomen: \"plus de … que\". Beispiele: \"plus grand que\", \"moins cher que\", \"aussi rapide que\""],"superlatifs":["Superlative","Setze den bestimmten Artikel vor \"plus\" oder \"moins\": \"le plus grand\", \"la plus belle\", \"les moins chers\". 'Von/in' heißt \"de\": \"le plus grand de la classe\". Beispiele: \"le plus grand\", \"la plus belle\", \"les moins chers\""],"meilleur-mieux":["meilleur oder mieux?","\"bon\" wird zu \"meilleur\" (Adjektiv, wird angeglichen): \"une meilleure idée\". \"bien\" wird zu \"mieux\" (Adverb, unveränderlich): \"elle chante mieux\". Sag nie \"plus bon\" oder \"plus bien\". Beispiele: \"meilleur\", \"mieux\", \"la meilleure idée\""],"adverbes-ment":["Adverbien auf -ment","Hänge \"-ment\" an das feminine Adjektiv: \"lent\" ergibt \"lentement\", \"heureux\" ergibt \"heureusement\". Nach Vokal hängst du es an die maskuline Form: \"vrai\" ergibt \"vraiment\". \"-ent\" wird zu \"-emment\": \"prudent\" ergibt \"prudemment\". Beispiele: \"lentement\", \"vraiment\", \"prudemment\""],"prep-pays-villes":["Länder und Städte","Städte: \"à Paris\", \"de Paris\". Feminine Länder: \"en France\", \"de France\". Maskuline Länder: \"au Japon\", \"du Japon\". Plural-Länder: \"aux États-Unis\", \"des États-Unis\". Beispiele: \"en France\", \"au Japon\", \"aux États-Unis\", \"à Paris\""],"depuis-pendant-il-y-a":["depuis, pendant, il y a","\"depuis\" + Präsens: etwas dauert noch an (\"j'habite ici depuis deux ans\"). \"pendant\" + Dauer: wie lange es dauerte (\"j'ai dormi pendant huit heures\"). \"il y a\" + Dauer: wie lange es her ist (\"il est parti il y a une heure\"). Beispiele: \"depuis deux ans\", \"pendant trois heures\", \"il y a une heure\""],"passe-recent":["Nahe Vergangenheit: venir de","Konjugiere \"venir\" im Präsens und hänge \"de\" + Infinitiv an: \"je viens de finir\", \"nous venons de partir\". Vor Vokal wird \"de\" zu \"d'\": \"il vient d'arriver\". Beispiele: \"je viens de manger\", \"ils viennent de partir\""],"imperatif-negatif":["Verneinter Imperativ","Setze \"ne … pas\" um das Imperativverb: \"ne pars pas !\", \"ne partons pas !\", \"ne partez pas !\". Pronomen bleiben vor dem Verb: \"ne le fais pas !\". Beispiele: \"ne parle pas\", \"ne partez pas\""],"imperatif-pronoms":["Imperativ mit Pronomen","Im bejahten Imperativ folgt das Pronomen dem Verb mit Bindestrich: \"regarde-moi\", \"parlez-nous\", \"dis-lui\". \"me\" wird zu \"moi\". Die Verneinung behält die normale Reihenfolge: \"ne me regarde pas\". Beispiele: \"regarde-moi\", \"dis-lui\", \"donne-le-moi\""],"rel-qui-que":["qui und que","\"qui\" ersetzt das Subjekt: \"la femme qui habite ici\". \"que\" ersetzt das direkte Objekt: \"le film que nous regardons\". \"que\" wird vor Vokal zu \"qu'\": \"le livre qu'il lit\". Beispiele: \"l'homme qui parle\", \"le livre que je lis\""],"rel-ou":["où: wo, wann","\"où\" verbindet einen Ort oder eine Zeit mit einem Nebensatz: \"la maison où elle habite\", \"le jour où nous sommes partis\". Es gilt für Ort und Zeit. Beispiele: \"la ville où j'habite\", \"le jour où\""],"il-faut":["il faut","\"il faut\" + Infinitiv heißt 'man muss': \"il faut partir\". \"il faut\" + Nomen heißt 'man braucht': \"il faut du temps\". \"il ne faut pas\" heißt 'man darf nicht'. Es ist ein unpersönliches Verb: nur \"il\". Beispiele: \"il faut travailler\", \"il faut du temps\""],"neg-jamais-plus-rien":["jamais, plus, rien, personne","Sie ersetzen \"pas\": \"ne … jamais\" (nie), \"ne … plus\" (nicht mehr), \"ne … rien\" (nichts), \"ne … personne\" (niemand). \"rien\" und \"personne\" können auch Subjekt sein: \"personne ne vient\". Beispiele: \"je ne mange jamais\", \"il ne travaille plus\", \"nous ne voyons personne\""],"quantite-de":["Menge + de","Nach Mengenangaben steht \"de\", ohne Artikel: \"beaucoup de travail\", \"un peu de sucre\", \"assez de temps\", \"trop de monde\", \"peu de gens\", \"une bouteille d'eau\". Beispiele: \"beaucoup de travail\", \"un peu de sucre\", \"trop de monde\""],"c-est-il-est":["c'est oder il est?","Nimm \"il est\" / \"elle est\" + Adjektiv oder Beruf allein: \"il est médecin\", \"elle est gentille\". Nimm \"c'est\", wenn ein Artikel oder Possessivum dabeisteht: \"c'est un médecin\", \"c'est mon frère\". Beispiele: \"c'est un médecin\", \"il est médecin\", \"elle est gentille\""],"q-inversion":["Inversion","Im gepflegten Französisch rückt das Verb vor das Subjektpronomen, mit Bindestrich: \"parlez-vous ?\", \"où vas-tu ?\", \"que font-ils ?\". Endet das Verb auf Vokal, kommt \"-t-\" dazu: \"aime-t-il ?\". Beispiele: \"parlez-vous\", \"où vas-tu\", \"que font-ils\""],"q-qui-que-quoi":["Wer und was","\"qui\" fragt nach Personen, \"que\" und \"qu'est-ce que\" nach Dingen: \"qu'est-ce que tu fais ?\". Nach einer Präposition nimm \"qui\" (Personen) oder \"quoi\" (Dinge): \"avec qui ?\", \"de quoi parles-tu ?\". Beispiele: \"qui est-ce ?\", \"qu'est-ce que tu fais ?\", \"de quoi parles-tu ?\""],"adj-irreguliers":["beau, nouveau, vieux","Diese drei haben vor maskulinem Vokal eine Sonderform: \"beau\" wird zu \"bel\", \"nouveau\" zu \"nouvel\", \"vieux\" zu \"vieil\". Feminin: \"belle\", \"nouvelle\", \"vieille\". Plural: \"beaux\", \"nouveaux\", \"vieux\". Beispiele: \"un bel homme\", \"une nouvelle voiture\", \"un vieil ami\""],"connecteurs-temps":["Zuerst, dann, schließlich","\"d'abord\" (zuerst), \"ensuite\" oder \"puis\" (dann), \"après\" (danach), \"enfin\" (schließlich) ordnen Handlungen: \"d'abord je mange, puis je pars, enfin j'arrive\". Beispiele: \"d'abord\", \"ensuite\", \"puis\", \"enfin\""],"si-present-futur":["si + Präsens, Futur","Für eine reale Möglichkeit: \"si\" + Präsens in der Bedingung, Futur (oder Imperativ) im Ergebnis. \"si tu viens, je serai content\", \"si vous avez le temps, appelez-moi\". Nie das Futur nach \"si\". Vor \"il\" heißt es \"s'il\". Beispiele: \"si tu viens, nous mangerons\", \"s'il pleut, je resterai\""],"savoir-connaitre":["savoir oder connaître?","\"savoir\" steht für Fakten und Fähigkeiten: \"je sais nager\", \"je sais où il habite\". \"connaître\" steht für das Kennen von Menschen, Orten und Dingen: \"je connais Marie\", \"je connais cette ville\". Beispiele: \"je sais nager\", \"je connais Paris\""],"pres-irreguliers-2":["Weitere unregelmäßige Verben","Lerne sie in Gruppen: \"lire\" (\"nous lisons\"), \"dire\" (\"vous dites\"), \"écrire\" (\"ils écrivent\"), \"voir\" (\"nous voyons\"), \"boire\" (\"ils boivent\"). Die \"nous\"-Form hilft beim Bilden des Imparfait. Beispiele: \"nous lisons\", \"vous dites\", \"ils écrivent\""],"meteo-il":["Das Wetter","Sag \"il fait\" + Adjektiv (\"il fait beau, froid, chaud\") und ein Verb für Regen und Schnee (\"il pleut\", \"il neige\"). Das Subjekt \"il\" ist leer und verändert sich nie. Frage: \"quel temps fait-il ?\" Beispiele: \"il fait beau\", \"il pleut\", \"il neige\""],"profession-sans-article":["Kein Artikel bei Berufen","Nach \"être\" steht bei Beruf, Nationalität oder Religion kein Artikel: \"il est médecin\", \"elle est française\". Mit Adjektiv nimmst du stattdessen \"c'est un\": \"c'est un bon médecin\". Beispiele: \"elle est infirmière\", \"il est professeur\""],"subj-il-faut-que":["Subjonctif: il faut que","Nach \"il faut que\" steht der Subjonctif. Regelmäßige Verben: Nimm den Präsensstamm von \"ils\" und hänge \"-e, -es, -e, -ions, -iez, -ent\" an: \"ils partent\" ergibt \"que je parte\". Die Formen \"nous\" und \"vous\" sehen aus wie der Imparfait. Beispiele: \"il faut que tu viennes\", \"il faut que je parte\""],"subj-vouloir-que":["vouloir que + Subjonctif","Wenn das Subjekt wechselt, verlangen \"vouloir que\", \"préférer que\", \"aimer mieux que\" und \"demander que\" den Subjonctif: \"je veux que tu viennes\". Bei gleichem Subjekt nimmst du den Infinitiv: \"je veux venir\". Beispiele: \"je veux que tu viennes\", \"elle veut que nous partions\""],"subj-irreguliers":["Unregelmäßiger Subjonctif","Auswendig lernen: \"être\" (\"que je sois\"), \"avoir\" (\"que j'aie, qu'il ait\"), \"aller\" (\"que j'aille\"), \"faire\" (\"que je fasse\"), \"pouvoir\" (\"que je puisse\"), \"savoir\" (\"que je sache\"), \"vouloir\" (\"que je veuille\"). Beispiele: \"que je sois\", \"qu'il ait\", \"que nous allions\", \"qu'ils fassent\""],"subj-emotions":["Gefühle + Subjonctif","Nach Gefühlsausdrücken (\"être content que\", \"être triste que\", \"regretter que\", \"avoir peur que\", \"être surpris que\") steht der Subjonctif, wenn das Subjekt wechselt. Beispiele: \"je suis content que tu sois là\", \"elle regrette que nous partions\""],"subj-vs-indic":["Indikativ oder Subjonctif","Gewissheit verlangt den Indikativ: \"je pense que\", \"je sais que\", \"il est sûr que\". Zweifel, Verneinung und Wille verlangen den Subjonctif: \"je ne pense pas que\", \"je doute que\", \"il faut que\". \"Penser que\" in der Frage geht mit beidem. Beispiele: \"je pense qu'il a raison\", \"je ne pense pas qu'il ait raison\""],"subj-conjonctions":["Konjunktionen + Subjonctif","Manche Konjunktionen verlangen immer den Subjonctif: \"pour que\" (damit), \"avant que\" (bevor), \"bien que\" (obwohl), \"à condition que\" (unter der Bedingung, dass), \"jusqu'à ce que\" (bis). \"après que\" verlangt den Indikativ. Beispiele: \"pour que tu comprennes\", \"avant que tu partes\", \"bien qu'il soit fatigué\""],"si-imparfait-cond":["si + Imparfait, Konditional","Für erdachte oder unwahrscheinliche Situationen: \"si\" + Imparfait, dann Konditional im Ergebnis. \"si j'étais riche, je voyagerais\". Nach \"si\" nie den Konditional. Beispiele: \"si j'avais de l'argent\", \"j'achèterais une maison\""],"cond-usage":["Konditional: Rat und Wünsche","Der \"conditionnel\" gibt Rat (\"tu devrais\"), drückt Wünsche aus (\"j'aimerais\") und macht höfliche Vorschläge (\"on pourrait\"). Mit \"devoir\", \"pouvoir\" und \"vouloir\" ist er sehr häufig. Beispiele: \"tu devrais dormir\", \"nous aimerions voyager\""],"cond-passe-regret":["Bedauern über die Vergangenheit","Für Dinge, die nicht geschehen sind: \"si\" + Plus-que-parfait, Conditionnel passé. \"si tu avais étudié, tu aurais réussi\". Der Conditionnel passé ist \"avoir\" oder \"être\" im Konditional + Partizip. Beispiele: \"si j'avais su\", \"je serais venu\""],"plus-que-parfait-forme":["Plus-que-parfait: Formen","Hilfsverb im \"imparfait\" + Partizip: \"j'avais mangé\", \"elle était partie\", \"nous nous étions levés\". Dieselben Regeln wie beim passé composé entscheiden über \"avoir\" oder \"être\" und über die Angleichung. Beispiele: \"j'avais fini\", \"nous étions partis\", \"elle avait mangé\""],"plus-que-parfait-usage":["Plus-que-parfait: Gebrauch","Der \"plus-que-parfait\" steht für eine Handlung, die vor einer anderen vergangenen Handlung oder einem vergangenen Zeitpunkt geschah: \"quand je suis arrivé, il était déjà parti\". Oft erklärt er eine Ursache: \"il était fatigué, il n'avait pas dormi\". Beispiele: \"le film avait déjà commencé\", \"il n'avait pas dormi\""],"di-present":["Indirekte Rede (Präsens)","Nach \"dire que\", \"répondre que\", \"expliquer que\" im Präsens bleibt die Zeit des Nebensatzes gleich; nur Pronomen und Wörter wie \"mon\" ändern sich: \"« j'ai faim »\" wird zu \"il dit qu'il a faim\". Beispiele: \"il dit qu'il est fatigué\", \"elle répond qu'elle ne sait pas\""],"di-questions":["Indirekte Fragen","Ja/Nein-Fragen nehmen \"si\": \"il demande si tu viens\". Fragewörter bleiben: \"où, quand, comment, pourquoi\". \"Qu'est-ce que\" wird zu \"ce que\", \"qu'est-ce qui\" wird zu \"ce qui\". Die Wortstellung ist die eines Aussagesatzes. Beispiele: \"il demande si je viens\", \"elle demande où j'habite\""],"di-passe":["Indirekte Rede (Vergangenheit)","Nach \"a dit que\" rücken die Zeiten zurück: Präsens wird zu \"imparfait\", Futur zu \"conditionnel\", passé composé zu \"plus-que-parfait\". Auch Zeitwörter ändern sich: \"demain\" wird zu \"le lendemain\". Beispiele: \"il a dit qu'il était fatigué\", \"elle a répondu qu'elle viendrait\""],"gerondif-formation":["Gérondif: Formen","Nimm die \"nous\"-Form des Präsens, streiche \"-ons\", hänge \"-ant\" an und setze \"en\" davor: \"nous travaillons\" ergibt \"en travaillant\". Ausnahmen: \"être\" ergibt \"en étant\", \"avoir\" ergibt \"en ayant\", \"savoir\" ergibt \"en sachant\". Beispiele: \"en travaillant\", \"en lisant\", \"en finissant\""],"gerondif-usage":["Gérondif: Gebrauch","Das \"gérondif\" drückt aus, dass zwei Handlungen gleichzeitig laufen (\"il chante en travaillant\"), wie etwas geschieht (\"on apprend en lisant\") oder eine Bedingung (\"en tournant à gauche, vous verrez la poste\"). Beide Verben haben dasselbe Subjekt. Beispiele: \"on apprend en lisant\", \"il s'est blessé en jouant\""],"rel-dont":["dont: von dem, dessen","\"dont\" ersetzt \"de\" + Nomen: \"je parle de ce livre\" wird zu \"le livre dont je parle\". Es heißt auch 'dessen': \"la fille dont le père est médecin\". Auch nach \"avoir besoin de\": \"ce dont j'ai besoin\". Beispiele: \"le livre dont je parle\", \"la fille dont le père est médecin\""],"rel-ce-qui-ce-que":["ce qui, ce que, ce dont","Steht kein Nomen davor, nimm \"ce qui\" (Subjekt), \"ce que\" (Objekt) und \"ce dont\" (mit \"de\"): \"ce qui se passe\", \"ce que tu veux\", \"ce dont j'ai besoin\". Beispiele: \"ce que tu veux\", \"ce qui se passe\", \"ce dont j'ai besoin\""],"pronoms-ordre":["Zwei Pronomen zusammen","Reihenfolge vor dem Verb: \"me, te, nous, vous\" + \"le, la, les\" + \"lui, leur\" + \"y\" + \"en\". \"me le\", \"te la\", \"nous les\", aber \"le lui\", \"les leur\": \"je le lui donne\". Beispiele: \"je le lui donne\", \"elle me les envoie\""],"y-en-ensemble":["il y en a","Stehen \"y\" und \"en\" zusammen, kommt \"y\" zuerst: \"il y en a\", \"il n'y en a plus\". \"en\" behält die Menge: \"il y en a trois\". Beispiele: \"il y en a\", \"nous y en avons\""],"imperatif-ordre-pronoms":["Imperativ: Pronomenfolge","Bejahend: Verb + direktes Objekt (\"le, la, les\") + indirektes (\"moi, lui, nous, leur\") + \"y\" / \"en\": \"donne-le-moi\", \"dis-le-lui\". \"moi\" wird vor \"en\" zu \"m'\": \"donne-m'en\". Verneint: normale Reihenfolge, \"ne me le donne pas\". Beispiele: \"donne-le-moi\", \"dis-le-lui\", \"donne-m'en\""],"pronoms-possessifs":["Possessivpronomen","Sie ersetzen Possessivum + Nomen und richten sich nach dem Nomen: \"le mien, la mienne, les miens, les miennes\", \"le tien\", \"le sien\", \"le nôtre\", \"le vôtre\", \"le leur\". \"Où est ma clé ? — Voici la mienne.\" Beispiele: \"le mien\", \"la tienne\", \"les nôtres\""],"pronoms-demonstratifs":["celui, celle, ceux, celles","Sie ersetzen 'der/die/das eine' und werden gefolgt von \"de\", \"qui\", \"que\" oder \"-ci / -là\": \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\", \"celles-là\". Beispiele: \"celui de gauche\", \"celle qui est ici\", \"ceux de Marc\""],"pronoms-indefinis":["Indefinitpronomen","\"quelqu'un\" (jemand), \"quelque chose\" (etwas), \"personne\" (niemand), \"rien\" (nichts), \"chacun\" (jeder), \"plusieurs\" (mehrere). Vor einem Adjektiv steht \"de\": \"quelque chose de bon\". Beispiele: \"quelqu'un\", \"quelque chose de sucré\", \"chacun\""],"adj-indefinis":["chaque, plusieurs, quelques","\"chaque\" + Nomen im Singular (jeder), \"plusieurs\" und \"quelques\" + Nomen im Plural (mehrere, ein paar). \"tout\" wird angeglichen: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Beispiele: \"chaque élève\", \"plusieurs voitures\", \"toute la journée\""],"pc-accord-cod":["Angleichung des Partizips mit avoir","Mit \"avoir\" richtet sich das Partizip nur dann nach dem direkten Objekt, wenn dieses vor dem Verb steht: \"j'ai acheté des fleurs\", aber \"les fleurs que j'ai achetées\", \"je les ai vues\". Beispiele: \"les fleurs que j'ai achetées\", \"je les ai vues\""],"passif-forme":["Passiv","\"être\" (in der nötigen Zeit) + Partizip, das zum Subjekt passt, + \"par\": \"la lettre est écrite par Paul\", \"les maisons ont été détruites par le feu\". Das Objekt des Aktivsatzes wird zum Subjekt. Beispiele: \"le roman est écrit par\", \"la porte est ouverte par\""],"se-passif":["Passiv mit se","Ein Verb in der 3. Person mit \"se\" hat passive Bedeutung, ohne Urheber: \"le vin se vend ici\", \"ça ne se dit pas\", \"cela se voit\". Sehr häufig in der Rede und in Regeln. Beispiele: \"ça se dit\", \"ce produit se vend partout\""],"etre-en-train-de":["être en train de","\"être en train de\" + Infinitiv betont, dass eine Handlung gerade läuft: \"je suis en train de lire\". Es entspricht 'gerade dabei sein, zu', wenn du es betonen willst: \"ne l'appelle pas, il est en train de dormir\". Beispiele: \"je suis en train de manger\", \"ils sont en train de partir\""],"pc-avoir-transitif":["Dasselbe Verb, zwei Hilfsverben","Haben \"sortir, monter, descendre, passer, rentrer, retourner\" ein direktes Objekt, ist das Hilfsverb \"avoir\": \"j'ai sorti la voiture\", \"elle a monté les escaliers\". Ohne Objekt \"être\": \"elle est sortie\". Beispiele: \"il a sorti la valise\", \"elle a monté les escaliers\""],"futur-anterieur":["Futur antérieur","\"avoir\" oder \"être\" im Futur simple + Partizip: \"j'aurai fini\", \"elle sera partie\". Es beschreibt eine Handlung, die vor einer anderen zukünftigen Handlung abgeschlossen ist: \"quand j'aurai fini, je t'appellerai\". Beispiele: \"quand j'aurai fini\", \"dès qu'elle sera arrivée\""],"quand-futur":["quand + Futur","Anders als im Deutschen steht nach \"quand\", \"dès que\", \"lorsque\" und \"aussitôt que\" das Futur, wenn die Handlung in der Zukunft liegt: \"dès qu'il arrivera, nous partirons\". \"Si\" ist die Ausnahme: nie mit Futur. Beispiele: \"quand je serai grand\", \"dès qu'il arrivera\""],"connecteurs-cause-consequence":["Grund und Folge","\"car\" und \"parce que\" geben einen Grund an; \"comme\" und \"puisque\" eröffnen den Satz mit einem bekannten Grund: \"comme il pleut, je reste\". \"donc\" und \"alors\" nennen die Folge: \"il pleut, donc je reste\". Beispiele: \"donc\", \"car\", \"comme\", \"puisque\""],"connecteurs-opposition":["Gegensatz","\"mais\", \"pourtant\" und \"cependant\" stellen zwei Ideen gegenüber. \"alors que\" vergleicht zwei Tatsachen: \"elle aime le thé, alors que son mari préfère le café\". \"malgré\" + Nomen heißt 'trotz': \"malgré la pluie\". Beispiele: \"pourtant\", \"alors que\", \"malgré la pluie\""],"but-pour-afin-de":["Zweck","Bei gleichem Subjekt: \"pour\" oder \"afin de\" + Infinitiv: \"je travaille pour gagner de l'argent\". Bei anderem Subjekt: \"pour que\" oder \"afin que\" + Subjonctif: \"il parle lentement pour que nous comprenions\". Beispiele: \"pour gagner de l'argent\", \"afin de rentrer\", \"pour que nous comprenions\""],"neg-ne-que-ni":["ne … que, ni … ni, aucun","\"ne … que\" heißt 'nur': \"je n'ai que dix euros\". \"ne … ni … ni\" heißt 'weder … noch': \"elle ne mange ni viande ni poisson\". \"ne … aucun\" heißt 'kein einziger': \"il n'a aucun ami\". Beispiele: \"je n'ai que dix euros\", \"ni viande ni poisson\", \"aucun ami\""],"neg-infinitif":["Verneinter Infinitiv","Beide Teile der Verneinung stehen zusammen vor dem Infinitiv: \"ne pas partir\", \"ne plus fumer\", \"ne jamais mentir\". \"Il m'a demandé de ne pas fumer\". Beispiele: \"ne pas fumer\", \"ne plus travailler\", \"ne jamais mentir\""],"q-lequel":["Lequel: welcher von","\"lequel\" ersetzt \"quel\" + Nomen und wird angeglichen: \"lequel\" (m. Sg.), \"laquelle\" (f. Sg.), \"lesquels\" (m. Pl.), \"lesquelles\" (f. Pl.). \"Quel sac ? Lequel ?\" Nach \"à\" und \"de\": \"auquel\", \"duquel\". Beispiele: \"lequel\", \"laquelle\", \"lesquels\""],"exclamations":["Ausrufe","\"quel\" + Nomen: \"quelle belle journée !\". \"comme\" oder \"que\" + Satz: \"comme il fait chaud !\", \"que c'est joli !\". Beachte das Leerzeichen vor \"!\" im Französischen. Beispiele: \"quelle belle journée !\", \"comme il fait chaud !\", \"que c'est joli !\""],"adv-place-pc":["Kurze Adverbien im passé composé","Kurze, häufige Adverbien (\"déjà, bien, mal, souvent, toujours, encore, trop, beaucoup\") stehen zwischen Hilfsverb und Partizip: \"j'ai déjà mangé\", \"il a bien compris\". Ortsadverbien und lange Adverbien stehen danach. Beispiele: \"elle a déjà fini\", \"il a bien compris\""],"comparatifs-avances":["Immer mehr, je mehr … desto mehr","\"de plus en plus\" (immer mehr), \"de moins en moins\" (immer weniger), \"plus … plus\" (je mehr … desto mehr), \"autant de … que\" (so viele … wie): \"elle a autant de livres que moi\". Beispiele: \"de plus en plus froid\", \"plus on travaille, plus on apprend\", \"autant de livres\""],"prep-verbes":["Verben mit Präposition","Viele Verben brauchen eine feste Präposition: \"penser à\", \"s'intéresser à\", \"répondre à\", \"parler de\", \"avoir besoin de\", \"avoir envie de\", \"rêver de\". Lerne sie mit dem Verb zusammen. Beispiele: \"penser à\", \"parler de\", \"avoir besoin de\", \"s'intéresser à\""],"prep-temps-en-dans":["en oder dans?","\"dans\" + Dauer: wann etwas geschieht, von jetzt an gerechnet (\"le film commence dans une heure\"). \"en\" + Dauer: wie lange etwas dauert (\"il a lu ce livre en deux jours\"). \"en\" steht auch bei Monaten und Jahren: \"en mai\", \"en 1998\". Beispiele: \"dans une heure\", \"en deux jours\""],"inf-apres-prepositions":["Präpositionen + Infinitiv","\"avant de\" + Infinitiv, \"après\" + Infinitiv Perfekt (\"avoir\" oder \"être\" + Partizip), \"sans\" + Infinitiv: \"avant de partir\", \"après avoir mangé\", \"sans dire au revoir\". Das Subjekt muss dasselbe sein. Beispiele: \"avant de manger\", \"après avoir mangé\", \"sans dire\""],"faire-causatif":["faire + Infinitiv","\"faire\" + Infinitiv heißt, etwas machen zu lassen (\"je fais réparer ma voiture\") oder jemanden etwas tun zu lassen (\"il fait rire les enfants\"). Der Infinitiv folgt direkt auf \"faire\". Beispiele: \"je fais réparer ma voiture\", \"il fait rire les enfants\""],"verbes-perception":["Sehen und hören + Infinitiv","Nach \"voir\", \"entendre\", \"regarder\", \"écouter\", \"sentir\" steht ein Infinitiv: \"je les entends jouer\", \"nous voyons passer le train\". Das Pronomen ist das Objekt des Wahrnehmungsverbs. Beispiele: \"je les entends chanter\", \"nous voyons passer le train\""],"voyelle-liaison-ecrite":["Sonderformen vor Vokal","Vor Vokal oder stummem h ändern manche Wörter sich, damit man leichter spricht: \"ma\" wird zu \"mon\" (\"mon amie\"), \"ce\" zu \"cet\" (\"cet homme\"), \"beau\" zu \"bel\" (\"un bel arbre\"), \"nouveau\" zu \"nouvel\", \"vieux\" zu \"vieil\". Beispiele: \"mon amie\", \"cet homme\", \"un bel arbre\""],"tout-tous-toutes":["tout, tous, toute, toutes","Als Adjektiv wird \"tout\" angeglichen: \"tout le monde\", \"toute la journée\", \"tous les jours\", \"toutes les semaines\". Als Pronomen heißt es 'alles' (\"j'ai tout compris\") oder 'alle' (\"ils sont tous là\", mit gesprochenem End-s). Beispiele: \"tous les jours\", \"toute la journée\", \"ils sont tous là\""],"subj-after-bien-que":["Bien que + Subjonctif","\"bien que\", \"quoique\" und \"encore que\" drücken einen Gegensatz aus und stehen immer mit dem Subjonctif, auch wenn die Tatsache sicher ist. Sage \"Bien que le projet soit coûteux, nous continuons\", nicht \"bien que le projet est\". Beispiele: \"Bien qu'il pleuve, nous sortons\", \"Quoiqu'elle soit jeune, elle dirige l'équipe\""],"subj-after-pour-que":["Zweck: pour que, afin que","\"pour que\" und \"afin que\" leiten einen Zweck ein und stehen mit dem Subjonctif. Das Subjekt des Zwecksatzes ist meist ein anderes als das Hauptsubjekt: \"Je répète pour que vous compreniez\". Bei gleichem Subjekt nimmst du \"pour\" oder \"afin de\" plus Infinitiv. Beispiele: \"Il parle lentement pour que nous comprenions\", \"Elle écrit afin que tout soit clair\""],"subj-after-avant-que":["Zeitgrenzen: avant que","\"avant que\" und \"jusqu'à ce que\" stehen mit dem Subjonctif, weil die Handlung noch nicht verwirklicht ist. Nach \"avant que\" wird oft ein \"ne\" ohne verneinende Bedeutung ergänzt: \"avant qu'il ne parte\". Bei gleichem Subjekt nimmst du \"avant de\" plus Infinitiv. Beispiele: \"Attends jusqu'à ce que je revienne\", \"Appelle avant que nous ne partions\""],"subj-a-moins-que-ne":["Ausnahme: à moins que","\"à moins que\" bedeutet \"es sei denn\" und verlangt den Subjonctif. Im gehobenen Französisch steht oft ein überflüssiges \"ne\" vor dem Verb (\"à moins qu'il ne vienne\"), das keine echte Verneinung ist. Danach stehen weder Konditional noch Futur. Beispiele: \"Je sors, à moins qu'il ne pleuve\", \"à moins que vous ne soyez occupé\""],"subj-a-condition-que":["Bedingung: à condition que","\"à condition que\" und \"pourvu que\" bedeuten \"unter der Bedingung, dass\" und stehen mit dem Subjonctif, nie mit Futur oder Konditional. \"Pourvu que\" kann auch einen Satz eröffnen, um eine Hoffnung auszudrücken: \"Pourvu qu'il vienne !\". Beispiele: \"Je viendrai à condition que vous m'invitiez\", \"Pourvu que tout se passe bien\""],"subj-vs-ind-opinion":["Meinungsverben: Modus","Nach \"penser que\" und \"croire que\" im Bejahten steht der Indicatif: \"Je pense qu'il a raison\". Im Verneinten oder in der Inversionsfrage entsteht Zweifel, und es steht der Subjonctif: \"Je ne pense pas qu'il ait raison\". Der Modus richtet sich danach, wie sicher sich der Sprecher ist. Beispiele: \"Je crois qu'elle viendra\", \"Je ne crois pas qu'elle vienne\""],"subj-emotion-doubt":["Gefühl, Zweifel, Notwendigkeit","Verben der Emotion (\"être content que\", \"regretter que\"), des Zweifels (\"douter que\") und der Notwendigkeit (\"il faut que\", \"il est essentiel que\") stehen mit dem Subjonctif, wenn die Subjekte verschieden sind. Der Satz drückt eine Reaktion oder ein Bedürfnis aus, keine bloße Tatsache. Beispiele: \"Je suis ravi que vous veniez\", \"Il faut que nous partions\""],"subj-irregular-forms":["Unregelmäßige Subjonctif-Stämme","Sieben häufige Verben haben unregelmäßige Subjonctif-Stämme: \"être\" (sois, soyons), \"avoir\" (aie, ayons), \"aller\" (aille, allions), \"faire\" (fasse), \"pouvoir\" (puisse), \"savoir\" (sache), \"vouloir\" (veuille). Lerne sie als ganze Formen; auch die nous- und vous-Formen von \"être\", \"avoir\", \"aller\" und \"vouloir\" haben einen eigenen Stamm. Beispiele: \"qu'elle aille\", \"que vous sachiez\", \"que tu aies\""],"subj-passe":["Subjonctif passé","Der Subjonctif passé besteht aus dem Subjonctif von \"avoir\" oder \"être\" plus Partizip Perfekt. Er zeigt, dass die Handlung vor der des Hauptverbs abgeschlossen ist: \"Je suis content que tu sois venu\". Wähle das Hilfsverb wie im passé composé und beachte die Angleichung. Beispiele: \"Il faut qu'ils aient fini\", \"Bien qu'elle soit partie\""],"subj-vs-infinitive":["Subjonctif oder Infinitiv","Haben beide Verben dasselbe Subjekt, bevorzugt das Französische den Infinitiv: \"Je veux partir\". Wechselt das Subjekt, steht \"que\" plus Subjonctif: \"Je veux que tu partes\". Das gilt auch für Wünsche, Gefühle und viele Konjunktionen (\"avant de\" oder \"avant que\"). Beispiele: \"Elle est contente d'être là\", \"Elle est contente que vous soyez là\""],"subj-superlative-relative":["Subjonctif nach Superlativ","Nach einem Superlativ (\"le plus\", \"le meilleur\") oder nach \"seul\", \"premier\", \"dernier\", \"unique\" steht im Relativsatz der Subjonctif, weil die Aussage ein persönliches Urteil ist. Mit \"jamais\" ist der Subjonctif passé üblich: \"le plus beau film que j'aie vu\". Beispiele: \"le seul homme qui sache\", \"la première fois que je le voie\""],"subj-relative-search":["Subjonctif bei gesuchtem Bezugswort","Beschreibt ein Relativsatz etwas, das du suchst, dir wünschst oder dessen Existenz du bezweifelst, steht der Subjonctif: \"Je cherche un livre qui soit simple\". Weißt du, dass es existiert, steht der Indicatif: \"J'ai un livre qui est simple\". Typische Auslöser: \"chercher\", \"vouloir\", \"il n'y a personne qui\", Fragen nach der Existenz. Beispiele: \"Y a-t-il quelqu'un qui puisse m'aider ?\""],"cond-passe-news":["Konditional für unbestätigte Meldungen","Journalisten verwenden das Konditional, oft das Konditional der Vergangenheit, für nicht bestätigte Informationen: \"Le ministre aurait démissionné\". Es bedeutet \"angeblich\" oder \"soll\" und der Autor bürgt nicht für die Tatsache. Für ein aktuelles Gerücht nimmst du das Konditional Präsens: \"Il serait malade\". Beispiele: \"Deux personnes seraient blessées\", \"selon certaines sources, le vol aurait été annulé\""],"si-plus-que-parfait":["Irreale Vergangenheit: si + plus-que-parfait","Für eine irreale Bedingung in der Vergangenheit steht \"si\" plus plus-que-parfait und im Hauptsatz das Konditional der Vergangenheit: \"Si j'avais su, je serais venu\". Setze nach \"si\" in dieser Bedeutung nie ein Konditional. Der Hauptsatz zeigt, was nicht geschehen ist. Beispiele: \"Si elle avait étudié, elle aurait réussi\", \"Si nous étions partis, nous aurions vu le concert\""],"si-mixed-conditions":["Gemischte Konditionalsätze","Ein gemischter Konditionalsatz verbindet eine vergangene Bedingung mit einem gegenwärtigen Ergebnis: \"si\" plus plus-que-parfait, dann das Konditional Präsens. Zeitwörter wie \"maintenant\" oder \"aujourd'hui\" im Hauptsatz zeigen, dass die Folge bis heute gilt. Beispiel: \"Si tu avais écouté, tu comprendrais\". Vergleiche mit dem rein vergangenen Muster: \"tu aurais compris\""],"hypothese-au-cas-ou":["Vorsorge: au cas où","\"au cas où\" drückt eine Vorsichtsmaßnahme gegen ein mögliches Ereignis aus und steht mit dem Konditional, nicht mit Subjonctif oder Futur. Es bedeutet \"für den Fall, dass\". Es kann am Satzanfang oder am Satzende stehen. Beispiele: \"Prenez un parapluie au cas où il pleuvrait\", \"Au cas où tu serais en retard, appelle-moi\""],"apres-que-indicatif":["après que + Indicatif","\"après que\" und \"dès que\" nennen eine Tatsache, die wirklich geschehen ist, und stehen daher mit dem Indicatif, nicht mit dem Subjonctif (anders als \"avant que\"). Das Verb nach \"après que\" steht in einer zusammengesetzten Zeit, die vor dem Hauptverb liegt: \"Après qu'il a fini, il est rentré\". Nach \"dès que\" mit Futur im Hauptsatz nimmst du das futur antérieur: \"Dès que tu auras fini, appelle-moi\""],"concordance-des-temps":["Zeitenfolge","Steht das Hauptverb in der Vergangenheit, rückt das Verb im Nebensatz zurück: Präsens wird zum imparfait, passé composé zum plus-que-parfait, Futur zum Konditional. Mische kein Hauptverb in der Vergangenheit mit einem Nebensatzverb im Präsens: \"Il pensait que nous étions partis\". Beispiele: \"Je savais que tu viendrais\", \"Elle disait qu'elle était fatiguée\""],"discours-indirect-passe":["Indirekte Rede in der Vergangenheit","In der indirekten Rede nach einem Verb der Vergangenheit (\"elle a dit que\") verschieben sich die Zeiten: Präsens zu imparfait, passé composé zu plus-que-parfait, Futur zu Konditional. Auch Zeitwörter ändern sich: \"demain\" wird zu \"le lendemain\", \"hier\" zu \"la veille\", \"aujourd'hui\" zu \"ce jour-là\". Beispiel: \"Il a dit qu'il viendrait le lendemain\""],"discours-indirect-questions":["Indirekte Fragen","In indirekten Fragen gilt die normale Wortstellung ohne Fragezeichen. \"Est-ce que\" und Ja-Nein-Fragen werden zu \"si\": \"Il a demandé si je venais\". \"Qu'est-ce que\" wird zu \"ce que\", und \"qu'est-ce qui\" zu \"ce qui\". Nach einem Verb der Vergangenheit verschieben sich die Zeiten. Beispiele: \"Elle m'a demandé ce que je voulais\", \"Il voulait savoir ce qui se passait\""],"discours-indirect-ordres":["Befehle und Bitten wiedergeben","Um einen Befehl oder eine Bitte wiederzugeben, nimmst du \"dire de\" oder \"demander de\" plus Infinitiv: \"Elle m'a dit de rentrer\". Die angesprochene Person steht mit \"à\" oder einem Pronomen: \"Il a demandé à ses voisins de baisser la musique\". Ein verneinter Befehl behält \"ne pas\" zusammen vor dem Infinitiv: \"Il nous a dit de ne pas toucher aux câbles\""],"accord-participe-cod-avant":["Angleichung bei vorangestelltem Objekt","Mit \"avoir\" gleicht sich das Partizip dem direkten Objekt nur an, wenn es vor dem Verb steht. Achte auf \"que\", ein Pronomen wie \"les\" oder ein Fragewort: \"Les lettres que Marie a écrites\", \"Quelle robe as-tu choisie ?\". Steht das Objekt danach, gibt es keine Angleichung: \"Marie a écrit des lettres\""],"accord-participe-pronominaux":["Partizip bei reflexiven Verben","Im passé composé eines reflexiven Verbs gleicht sich das Partizip dem Reflexivpronomen an, wenn es direktes Objekt ist: \"Les amies se sont retrouvées\". Es bleibt unverändert, wenn das Pronomen indirektes Objekt ist oder ein anderes Objekt folgt: \"Elle s'est lavé les mains\", \"Ils se sont envoyé des messages\". Frage dich, ob \"se\" \"à qui ?\" oder \"qui ?\" bedeutet"],"participe-present-gerondif":["Partizip, Gérondif, Adjektiv","Das Gérondif \"en + -ant\" sagt, wie oder wann etwas geschieht, und ist unveränderlich: \"Il s'est blessé en coupant du bois\". Das Partizip Präsens ersetzt einen Nebensatz und ist ebenfalls unveränderlich: \"Les enfants jouant dans le jardin\". Das Verbaladjektiv gleicht sich dem Nomen an: \"une histoire fascinante\", \"des résultats surprenants\""],"passif-et-alternatives":["Passiv und Alternativen","Das Passiv besteht aus \"être\" + Partizip: \"Les résultats ont été annoncés par le jury\". Das Französische bevorzugt oft Alternativen: ein Reflexivverb für allgemeine Tatsachen (\"Le fromage se mange après le plat\"), \"on\" oder \"se faire\" für etwas, das dem Subjekt widerfährt (\"Il s'est fait voler son sac\")"],"causatif-faire-laisser":["Kausatives faire und laisser","\"Faire\" + Infinitiv bedeutet, dass man etwas machen lässt: \"Nous avons fait refaire la cuisine\". \"Laisser\" + Infinitiv bedeutet erlauben: \"Le professeur a laissé les élèves partir\". Das Partizip \"fait\" bleibt vor dem Infinitiv unverändert: \"Ce film m'a fait pleurer\""],"pronoms-relatifs-composes":["Zusammengesetzte Relativpronomen","Nach einer Präposition nimmst du \"lequel\", \"laquelle\", \"lesquels\" oder \"lesquelles\", passend zum Nomen: \"la table sur laquelle\", \"les amis chez lesquels\". Mit \"à\" verschmelzen sie: \"auquel\", \"auxquels\", \"auxquelles\", \"à laquelle\". Mit \"de\" ergeben sie \"duquel\", \"desquels\", \"de laquelle\""],"pronom-relatif-dont":["Das Relativpronomen dont","\"Dont\" ersetzt \"de\" + Nomen in einem Relativsatz: \"L'ordinateur dont j'ai besoin\" (avoir besoin de). Es drückt auch Besitz aus, mit dem Nomen direkt danach: \"l'écrivain dont le dernier roman\". Und es führt einen Teil einer Gruppe ein: \"trois enfants, dont deux vivent à l'étranger\""],"ce-qui-ce-que-ce-dont":["Ce qui, ce que, ce dont","\"Ce\" + Relativpronomen bezieht sich auf einen Gedanken oder eine unbenannte Sache. \"Ce qui\" ist Subjekt (\"Ce qui m'inquiète\"), \"ce que\" Objekt (\"ce que tu veux\"). Nimm \"ce dont\" für Verben mit \"de\" (\"ce dont tu as envie\") und \"ce à quoi\" für Verben mit \"à\" (\"ce à quoi il s'intéresse\")"],"pronoms-doubles-ordre":["Reihenfolge von zwei Pronomen","Vor dem Verb steht bei me, te, nous und vous das indirekte Pronomen zuerst: \"Je te le rends\". Bei der dritten Person kommt das direkte zuerst: \"Je le lui donne\"; \"en\" steht immer zuletzt: \"Je lui en ai parlé\". Nach einem bejahten Imperativ ist die Reihenfolge direkt, dann indirekt: \"Donne-les-moi\""],"pronoms-y-en-avances":["Fortgeschrittenes y und en","\"En\" ersetzt \"de\" + Nomen oder eine Menge, und die Zahl bleibt stehen: \"J'en ai acheté trois\". \"Y\" ersetzt \"à\" oder einen Ort: \"J'y pense tout le temps\". Im bejahten Imperativ folgen sie dem Verb und verbinden sich: \"Donnez-m'en un kilo\""],"mise-en-relief":["Hervorhebung mit c'est...qui/que","\"C'est ... qui\" hebt das Subjekt hervor, \"c'est ... que\" ein Objekt oder eine Ergänzung: \"C'est moi qui ai fait le gâteau\", \"C'est demain que nous partons\". Bei einem Nomen im Plural nimmst du \"ce sont\": \"Ce sont mes voisins que j'ai invités\". Das Verb nach \"qui\" richtet sich nach dem hervorgehobenen Element"],"inversion-peut-etre":["Inversion nach Satzadverbien","Im gehobenen Französisch ziehen \"peut-être\", \"sans doute\" und \"aussi\" (im Sinn von \"deshalb\") am Satzanfang die Inversion von Subjekt und Verb nach sich: \"Peut-être viendra-t-il demain\". Bei einem Nomen als Subjekt wird es als Pronomen wiederholt. Ergänze \"-t-\", wenn das Verb vor \"il\" oder \"elle\" auf einen Vokal endet: \"viendra-t-elle\""],"ne-expletif":["Das ne explétif","Nach Verben der Furcht (\"craindre que\"), nach \"avant que\" und nach Komparativen der Ungleichheit setzt das gehobene Französisch ein \"ne\" ohne verneinende Bedeutung: \"Je crains qu'il ne pleuve\", \"avant qu'il ne fasse nuit\", \"plus grand que je ne pensais\". Es ist in der gesprochenen Sprache optional und steht nie mit \"pas\""],"connecteurs-concession-opposition":["Einräumung und Gegensatz","\"Bien que\" + Subjonctif und \"malgré\" + Nomen drücken eine Einräumung aus: \"Malgré la pluie, nous sommes sortis\". \"Alors que\" + Indicatif stellt zwei Tatsachen gegenüber: \"Paul adore la mer, alors que sa femme préfère la montagne\". \"Pourtant\", \"cependant\" und \"en revanche\" verbinden zwei Sätze"],"nominalisation":["Verben zu Nomen machen","Die Nominalisierung macht Texte knapper und formeller. Verben werden mit Endungen wie -tion, -ment, -ure oder -ée zu Nomen: \"ouvrir\" ergibt \"l'ouverture\", \"augmenter\" ergibt \"l'augmentation\", \"arriver\" ergibt \"l'arrivée\". Auch bei Adjektiven: \"difficile\" ergibt \"la difficulté\". Prüfe das Genus des neuen Nomens"],"tout-accord":["Tout: Adjektiv, Pronomen, Adverb","Als Adjektiv gleicht sich \"tout\" dem Nomen an: \"tous les magasins\", \"toutes les fenêtres\". Als Adverb im Sinn von \"ganz\" ist es unveränderlich, außer vor einem weiblichen Adjektiv, das mit Konsonant beginnt: \"elle est tout étonnée\", aber \"elles sont toutes timides\""],"prepositions-apres-verbes":["Präpositionen nach Verben","Manche Verben haben eine feste Präposition, die die Bedeutung verändern kann. \"Penser à\" heißt an etwas denken: \"Je pense à mes vacances\"; \"penser de\" fragt nach einer Meinung: \"Que penses-tu de ce film ?\". Lerne Paare wie \"s'habituer à\" und \"se méfier de\" als Einheit"],"infinitif-passe":["Der Infinitiv der Vergangenheit","\"Après\" + \"avoir\" oder \"être\" + Partizip Perfekt sagt, dass eine Handlung vor der Haupthandlung geschah: \"Après avoir écrit la lettre, il l'a postée\". Beide Handlungen müssen dasselbe Subjekt haben. Bewegungsverben und reflexive Verben nehmen \"être\" und gleichen sich an: \"Après être rentrée\", \"Après nous être reposés\""],"a-regard-pronoms-lequel":["Fragendes lequel","\"Lequel\" fragt nach einer Auswahl unter bekannten Dingen und gleicht sich ihnen an: \"Lequel de ces chemins ?\", \"Laquelle de tes amies ?\". Mit \"à\" oder \"de\" verschmilzt es: \"Auquel de ces clients as-tu téléphoné ?\", \"Duquel parles-tu ?\". Nimm \"quel\" nur direkt vor einem Nomen"]};
